#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){string a,b;cin>>a>>b;
int i=a.size()-1,j=b.size()-1,carry=0;string r;
while(i>=0||j>=0||carry){int s=carry;
if(i>=0)s+=a[i--]-'0';
if(j>=0)s+=b[j--]-'0';
r+=(char)('0'+s%10);carry=s/10;}
reverse(r.begin(),r.end());
printf("%s\n",r.c_str());return 0;}

